import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    max_xor = 0
    # brute force all subarrays
    for i in range(n):
        current = 0
        for j in range(i, n):
            current ^= a[j]
            max_xor = max(max_xor, current)
    print(max_xor)

if __name__ == "__main__":
    main()
"}

