def is_beautiful(s, k):
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1
    for c in count:
        if c % k != 0:
            return False
    return True


def next_beautiful_string(n, k, s):
    if n % k != 0:
        return -1

    if is_beautiful(s, k):
        return s

    # Try to find next beautiful string >= s
    # Backtracking approach to build the string character by character

    # Track counts of each letter
    count = [0] * 26

    def backtrack(pos):
        # pos is the current position we're trying to fill
        if pos == n:
            # We've built a complete string
            chars = [''] * n
            for i in range(n):
                chars[i] = chr(26 + count[i])
            return ''.join(chars)

        # Try each possible character from 'a' to 'z'
        for c in range(26):
            char = chr(c + ord('a'))

            # Check if we can use this character
            if count[c] >= n // k:
                continue

            # Check if this character makes the string >= s
            if pos < len(s):
                if char < s[pos]:
                    continue

            # Try using this character
            count[c] += 1

            # Recursively build the rest of the string
            result = backtrack(pos + 1)
            if result is not None:
                return result

            # Backtrack
            count[c] -= 1
        return None

    return backtrack(0)


def solve():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    T = int(input[idx]); idx += 1
    results = []

    for _ in range(T):
        n = int(input[idx]); idx += 1
        k = int(input[idx]); idx += 1
        s = input[idx]; idx += 1

        result = next_beautiful_string(n, k, s)
        results.append(str(result) if result != -1 else '-1')

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

