import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    p = [int(next(it)) for _ in range(n)]

    # Build adjacency list for swap graph
    adj = [[] for _ in range(n)]
    for i in range(n):
        row = next(it)
        for j, ch in enumerate(row):
            if ch == '1':
                adj[i].append(j)

    # Find connected components using BFS
    visited = [False] * n
    components = []

    for start in range(n):
        if not visited[start]:
            # BFS to find all nodes in this component
            q = [start]
            visited[start] = True
            comp = [start]
            while q:
                u = q.pop(0)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        comp.append(v)
                        q.append(v)
            components.append(comp)

    # For each component, collect positions and values
    # Then sort both and assign smallest to smallest
    result = [0] * n

    for comp in components:
        positions = sorted(comp)  # sort by index
        values = []
        for pos in comp:
            values.append(p[pos])
        values.sort()

        for pos, val in zip(positions, values):
            result[pos] = val

    print(' '.join(map(str, result)))

if __name__ == '__main__':
    solve()
"}

