def solve():
    s = input().strip()

    # Count directions
    count = {'L': 0, 'R': 0, 'U': 0, 'D': 0}
    for ch in s:
        count[ch] += 1

    # Calculate net displacement
    x = count['R'] - count['L']
    y = count['U'] - count['D']

    # If total displacement is odd, impossible
    if abs(x) + abs(y) % 2 == 1:
        print(-1)
    else:
        print(max(abs(x), abs(y)))

solve()
