import sys

def sum_digits(x):
    """Return the sum of digits of x."""
    return sum(int(d) for d in str(x))

def get_divisors(n):
    """Return all divisors of n."""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

n = int(sys.stdin.readline())

