import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Find shortest cycle
    # Check for triangles first: if any bit appears in at least 3 numbers
    bit_masks = [[] for _ in range(61)]  # 0 to 60 bits
    for i in range(n):
        num = a[i]
        for j in range(61):
            if num & (1 << j):
                bit_masks[j].append(i)

    # Check for triangles
    for bit in range(61):
        if len(bit_masks[bit]) >= 3:
            print(3)
            return

    # Check for cycles of length 4
    # For each pair of bits, check if there are numbers with both bits
    for i in range(61):
        for j in range(i + 1, 61):
            # Find numbers with both bits i and j
            common = []
            for k in range(n):
                if (a[k] & (1 << i)) and (a[k] & (1 << j)):
                    common.append(k)
            if not common:
                continue

            # Check if there are numbers with only bit i
            only_i = [k for k in range(n) if (a[k] & (1 << i)) and not (a[k] & (1 << j))]
            # Check if there are numbers with only bit j
            only_j = [k for k in range(n) if (a[k] & (1 << j)) and not (a[k] & (1 << i))]

            if only_i and only_j:
                print(4)
                return

    # If no cycles found
    print(-1)

if __name__ == "__main__":
    solve()
