total = sum(a)

if total % 2 != 0:
    print("NO")
else:
    target = total // 2
    prefix_sum = 0
    found = False

    for i in range(n):
        prefix_sum += a[i]

        # Check if we can split here without moving
        if prefix_sum == target:
            found = True
            break

        # Check if we can move an element to make it work
        if prefix_sum < target:
            # Need to add an element from the suffix to the prefix
            # The element would be a[i+1], a[i+2], ..., a[n-1]
            # We need to find an element that, when added, makes prefix_sum + element == target
            # Also check if there's an element we can move from the prefix to the suffix
            # (prefix_sum - element == target)

            # Check adding from suffix
            for j in range(i+1, n):
                if prefix_sum + a[j] == target:
                    found = True
                    break
                if prefix_sum + a[j] > target:
                    break
        else:  # prefix_sum > target
            # Need to remove an element from the prefix
            # The element would be a[0], a[1], ..., a[i]
            for j in range(i+1):
                if prefix_sum - a[j] == target:
                    found = True
                    break
                if prefix_sum - a[j] < target:
                    break

        if found:
            break

    print("YES" if found else "NO")
