def is_prime(n):
    """Check if n is a prime number."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def get_possible_prev_values(x):
    """Get all possible previous values that could lead to x in one turn."""
    possible_prev = set()

    for p in range(2, x):
        if not is_prime(p):
            continue

        # Check if p is a valid prime for this value
        if x % p == 0:
            # x could have come from itself (if there's a prime divisor < x)
            # We need to ensure there's a prime divisor q < x that divides x
            has_divisor = False
            for q in range(2, x):
                if x % q == 0:
                    has_divisor = True
                    break

            if has_divisor:
                possible_prev.add(x)
        else:
            # x could have come from the value before applying p
            prev = x - (p - (x % p))
            if prev >= 1:
                # Check if there's a prime divisor q < prev that divides prev
                has_divisor = False
                for q in range(2, prev):
                    if prev % q == 0:
                        has_divisor = True
