import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    h = next(it)
    v = next(it)

    # Build adjacency list
    def build_graph():
        adj = [[] for _ in range(n * m)]
        for i in range(n):
            for j in range(m):
                node = i * m + j
                if h[i] == '>':
                    if j + 1 < m:
                        adj[node].append(i * m + (j + 1))
                elif h[i] == '<':
                    if j - 1 >= 0:
                        adj[node].append(i * m + (j - 1))
                if v[j] == '^':
                    if i + 1 < n:
                        adj[node].append((i + 1) * m + j)
                elif v[j] == 'v':
                    if i - 1 >= 0:
                        adj[node].append((i - 1) * m + j)
        return adj

    adj = build_graph()

    # DFS on original graph from (0,0) = node 0
    def dfs_reach(start, adj, reach):
        stack = [start]
        reach[start] = True
        while stack:
            node = stack.pop()
            for nei in adj[node]:
                if not reach[nei]:
                    reach[nei] = True
                    stack.append(nei)

    # DFS on reversed graph from (0,0) = node 0
    def dfs_rev_reach(start, adj, reach):
        stack = [start]
        reach[start] = True
        while stack:
            node = stack.pop()
            for nei in adj[node]:
                if not reach[nei]:
                    reach[nei] = True
                    stack.append(nei)

    # Check if all nodes are reachable from (0,0) and all nodes can reach (0,0)
    reach = [False] * (n * m)
    dfs_reach(0, adj, reach)
    if sum(reach) != n * m:
        print("NO")
        return

    rev_reach = [False] * (n * m)
    dfs_rev_reach(0, adj, rev_reach)
    if sum(rev_reach) != n * m:
        print("NO")
        return

    print("YES")

