import sys
from collections import defaultdict

def solve():
    MOD = 10**9 + 7
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m = int(data[0])
    n = int(data[1])

    # Convert binary strings to integers
    T = []
    idx = 2
    for _ in range(n):
        s = data[idx]
        idx += 1
        T.append(int(s, 2))

    # Memoization cache
    cache = {}

    def count_subsets(S):
        if tuple(sorted(S)) in cache:
            return cache[tuple(sorted(S))]

        # Check closure under XOR and AND
        is_closed = True
        for i in range(len(S)):
            for j in range(i + 1, len(S)):
                xor_val = S[i] ^ S[j]
                and_val = S[i] & S[j]

                # If the result of the operation is in T, it must also be in S
                if xor_val in T and xor_val not in S:
                    is_closed = False
                    break
                if and_val in T and and_val not in S:
                    is_closed = False
                    break
            if not is_closed:
                break

        if is_closed:
            # Count this subset and its supersets
            result = 1
            for i in range(len(S)):
                new_S = set(S)
                new_S.add(T[i])
                result = (result + count_subsets(new_S)) % MOD
            return result
        else:
            return 1  # Count the empty set

    # Start with empty set
    result = count_subsets(set())

    print(result % MOD)

if __name__ == "__main__":
    solve()
