# Union-Find data structure
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size + 1))
        self.size = [1] * (size + 1)
    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]
    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        if self.size[x_root] < self.size[y_root]:
            x_root, y_root = y_root, x_root
        self.parent[y_root] = x_root
        self.size[x_root] += self.size[y_root]

result = []

for q in queries:
    uf = UnionFind(n)
    for w, u, v in edges:
        if w <= q:
            uf.union(u, v)

    total_pairs = 0
    for i in range(1, n + 1):
        if uf.find(i) == i:
            total_pairs += uf.size[i] * (uf.size[i] - 1) // 2

    result.append(str(total_pairs))

print(' '.join(result))
