import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Read edges
    edges = []
    degree = [0] * (n + 1)
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        edges.append((u, v))
        degree[u] += 1
        degree[v] += 1

    # Check if graph is connected
    # Using BFS
    visited = [False] * (n + 1)
    from collections import deque
    q = deque()

    # Start from vertex 1 if degree[1] > 0, else start from a vertex with non-zero degree
    start = 1
    for i in range(1, n + 1):
        if degree[i] > 0:
            start = i
            break

    if degree[start] == 0:
        # All vertices have degree 0
        print(0)
        return

    q.append(start)
    visited[start] = True

    while q:
        u = q.popleft()
        for v, _ in edges:
            if u == v:
                if degree[u] > 0:
                    # This is a loop, we can traverse it
                    # But we need to check if it's part of a connected component
                    # Since loops don't connect to other vertices, they don't affect connectivity
                    pass
            else:
                if not visited[v] and degree[v] > 0:
                    visited[v] = True
                    q.append(v)

    # Check if all non-zero degree vertices are visited
    connected = True
    for i in range(1, n + 1):
        if degree[i] > 0 and not visited[i]:
            connected = False
            break

    # Count vertices with odd degree
    odd_count = 0
    for i in range(1, n + 1):
        if degree[i] % 2 == 1:
            odd_count += 1

    if connected and odd_count % 2 == 0:
        print(m * (m - 1) // 2)
    else:
        print(0)

if __name__ == "__main__":
    solve()
