def is_good_subarray(values):
    """Check if a subarray is good (doesn't contain a bad triple)."""
    n = len(values)
    for i in range(n):
        for k in range(i + 2, n):
            j = i + 1
            # Check if a_j is between a_i and a_k
            if min(values[i], values[k]) <= values[j] <= max(values[i], values[k]):
                return False
    return True

def count_good_subarrays(a):
    """Count the number of good subarrays in array a."""
    n = len(a)
    count = 0

    # All subarrays of length 1 and 2 are good
    count += n
    count += n * (n - 1) // 2

    # Check all subarrays of length ≥ 3
    for l in range(n - 2 + 1):
        for r in range(l + 2, n):
            subarray = a[l:r+1]
            if is_good_subarray(subarray):
                count += 1

    return count

