def solve(arr, turn):
    """Return (alice_score, bob_score) for the current state"""
    if not arr:
        return (0, 0)

    # Memoization cache
    memo = {}

    def dfs(arr, turn):
        if tuple(arr) in memo:
            return memo[tuple(arr)]

        if not arr:
            return (0, 0)

        if turn == 'Alice':
            # Alice's turn: pick an element that maximizes her score while minimizing Bob's
            best_alice = -1
            best_bob = 0

            for i in range(len(arr)):
                new_arr = arr[:i] + arr[i+1:]
                alice_points = arr[i] if arr[i] % 2 == 0 else 0
                alice_score, bob_score = dfs(new_arr, 'Bob')
                total_alice = alice_score + alice_points

                if total_alice > best_alice or (total_alice == best_alice and bob_score < best_bob):
                    best_alice = total_alice
                    best_bob = bob_score

            memo[tuple(arr)] = (best_alice, best_bob)
            return (best_alice, best_bob)
        else:  # Bob's turn
            # Bob's turn: pick an element that maximizes his score while minimizing Alice's
            best_alice = 0
            best_bob = -1

            for i in range(len(arr)):
                new_arr = arr[:i] + arr[i+1:]
                bob_points = arr[i] if arr[i] % 2 == 1 else 0
                alice_score, bob_score = dfs(new_arr, 'Alice')
                total_bob = bob_score + bob_points

                if total_bob > best_bob or (total_bob == best_bob and alice_score < best_alice):
                    best_alice = alice_score
                    best_bob = total_bob

            memo[tuple(arr)] = (best_alice, best_bob)
            return (best_alice, best_bob)

    return dfs(arr, 'Alice')

t = int(input())
for _ in range(t):
    n = int(input())
    arr = list(map(int, input().split()))
    alice_score, bob_score = solve(arr, 'Alice')

    if alice_score > bob_score:
        print("Alice")
    elif alice_score < bob_score:
        print("Bob")
    else:
        print("Tie")
