def can_place_bars(positions, k, max_gap, first, last):
    """Check if we can place k bars with max gap no more than max_gap"""
    count = 1  # first position is always used
    prev = first

    # Place the rest of the bars
    for pos in positions:
        if pos == last:
            count += 1
            break
        if pos - prev - 1 <= max_gap:
            prev = pos
            count += 1

    return count >= k


def solve():
    n, k = map(int, input().split())
    s = input()

    # Find all available positions (0-indexed)
    positions = []
    for i in range(n):
