import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    # Initialize the string with 'a's (the smallest lexicographical character)
    # We'll determine the maximum length needed
    max_len = 0

    for _ in range(n):
        ti = next(it)
        ki = int(next(it))

        for _ in range(ki):
            pos = int(next(it))
            max_len = max(max_len, pos + len(ti) - 1)

    # Create the result array
    result = ['a'] * max_len

    for _ in range(n):
        ti = next(it)
        ki = int(next(it))

        for _ in range(ki):
            pos = int(next(it))
            for i in range(len(ti)):
                result[pos - 1 + i] = ti[i]

    print(''.join(result))

if __name__ == '__main__':
    solve()
