def can_reach(n, m, horizontal, vertical):
    # Create adjacency list
    graph = [[] for _ in range(n * m)]

    # Add horizontal moves
    for i in range(n):
        for j in range(m - 1):
            if horizontal[i] == '>':
                # West to east: move from (i, j) to (i, j+1)
                graph[i * m + j].append(i * m + j + 1)
            else:  # '<'
                # East to west: move from (i, j) to (i, j-1)
                graph[i * m + j + 1].append(i * m + j)

    # Add vertical moves
    for j in range(m):
        for i in range(n - 1):
            if vertical[j] == '^':
                # South to north: move from (i, j) to (i+1, j)
                graph[i * m + j].append((i + 1) * m + j)
            else:  # 'v'
                # North to south: move from (i, j) to (i-1, j)
                graph[(i + 1) * m + j].append(i * m + j)

    # Find SCCs using Kosaraju's algorithm
    visited = [False] * (n * m)
    order = []

    def dfs1(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(n * m):
        if not visited[i]:
            dfs1(i)

    # Transpose graph
    transpose = [[] for _ in range(n * m)]
    for u in range(n * m):
        for v in graph[u]:
            transpose[v].append(u)

    visited = [False] * (n * m)
    scc_count = 0

    def dfs2(u, component):
        visited[u] = True
        component.append(u)
        for v in transpose[u]:
            if not visited[v]:
                dfs2(v, component)

    for u in reversed(order):
        if not visited[u]:
            component = []
            dfs2(u, component)
            scc_count += 1

    return scc_count == 1

