def solve():
    # Read input
    n, k, l = map(int, input().split())
    s = input().strip()

    # Count initial lowercase and uppercase letters
    lower = sum(1 for ch in s if ch.islower())
    upper = n - lower

    # Find all positions where we can flip segments of length l
    # and have all lowercase or all uppercase letters
    all_lower = []
    all_upper = []

    for i in range(n - l + 1):
        segment = s[i:i+l]
        if all(ch.islower() for ch in segment):
            all_lower.append(i)
        elif all(ch.isupper() for ch in segment):
            all_upper.append(i)

    # Greedily use best operations
    while k > 0:
        if lower <= upper:
            # We're on the lower side, flip an all-uppercase segment
            if all_upper:
                # Flip this segment
                upper -= l
                lower += l
                k -= 1
            else:
                break
        else:
            # We're on the upper side, flip an all-lowercase segment
            if all_lower:
                # Flip this segment
                lower -= l
                upper += l
                k -= 1
            else:
                break

    print(min(lower, upper))

if __name__ == "__main__":
    solve()
