import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if (a[i] & a[j]) != 0:
                graph[i].append(j)
                graph[j].append(i)

    # Check for cycles
    min_cycle_length = -1

    # BFS to find shortest cycle starting from each node
    for start in range(n):
        visited = [-1] * n
        queue = [(start, 0)]  # (node, distance_from_start)
        visited[start] = 0

        while queue:
            node, dist = queue.pop(0)

            # If we've returned to start and we've made a cycle
            if node == start and dist > 0:
                # Cycle length = dist (number of edges in cycle)
                # But we need to count nodes, not edges
                cycle_length = dist
                if min_cycle_length == -1 or cycle_length < min_cycle_length:
                    min_cycle_length = cycle_length
                break

            for neighbor in graph[node]:
                if visited[neighbor] == -1:
                    visited[neighbor] = dist + 1
                    queue.append((neighbor, dist + 1))

    print(min_cycle_length if min_cycle_length != -1 else -1)

solve()
