def solve():
    n = int(input())

    # Group people by their political views
    count_00 = []  # supports neither
    count_10 = []  # supports only Alice
    count_01 = []  # supports only Bob
    count_11 = []  # supports both

    for _ in range(n):
        s, a = input().split()
        a = int(a)
        if s == "00":
            count_00.append(a)
        elif s == "10":
            count_10.append(a)
        elif s == "01":
            count_01.append(a)
        elif s == "11":
            count_11.append(a)

