def sum_digits(x):
    """Return the sum of digits of x."""
    return sum(int(d) for d in str(x))

n = int(input())

# Try all x from 1 up to some reasonable upper bound
# Since x(x + s(x)) = n, and s(x) <= 9 * number_of_digits(x)
# We know x <= sqrt(n), but s(x) can be significant
# Let's try x from 1 to 100000 (this is a bit arbitrary but should work)
x = 1
while x * x <= n * 2:  # We'll check up to a factor of 2 for safety
    if (n - x * x) % x == 0:
        s = sum_digits(x)
        if s == (n - x * x) // x:
            print(x)
            exit()
    x += 1

# Also check values just below sqrt(n) more carefully
x = int(n ** 0.5) - 1000
while x > 0:
    if x * x <= n * 2:
        if (n - x * x) % x == 0:
            s = sum_digits(x)
            if s == (n - x * x) // x:
                print(x)
                exit()
    x -= 1

print(-1)
