def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    nodes = []
    parent_set = set()
    root = None
    for i in range(n):
        v = int(next(it))
        l = int(next(it))
        r = int(next(it))
        nodes.append((v, l, r))
        if l != -1:
            parent_set.add(l)
        if r != -1:
            parent_set.add(r)

    # Find root: vertex index not in parent_set
    for i in range(1, n + 1):
        if i not in parent_set:
            root = i
            break

    # Simulate search algorithm for each vertex
    count = 0
    for idx in range(n):
        v, l, r = nodes[idx]
        # simulate search from root for target = v
        curr_idx = root
        while curr_idx != -1:
            curr_v, curr_l, curr_r = nodes[curr_idx - 1]
            if curr_v == v:
                # Success, don't count
                break
            if v < curr_v:
                curr_idx = curr_l
            else:
                curr_idx = curr_r
        else:
            # curr_idx == -1, fail
            count += 1

    print(count)

if __name__ == "__main__":
    solve()
