import sys

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    # Group consecutive equal characters
    groups = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 0
        while i < len(s) and s[i] == char:
            count += 1
            i += 1
        groups.append((char, count))

    result = []
    for char, count in groups:
        if char in {'a', 'e', 'i', 'o', 'u', 'y'}:
            # It's a vowel
            if char in {'e', 'o'} and count == 2:
                # Exception: keep exactly 2 'e' or 'o'
                result.append(char * count)
            elif char in {'e', 'o'}:
                # Combine 'e' or 'o' if count != 2
                result.append(char)
            else:
                # Other vowels: combine if count > 1
                if count > 1:
                    result.append(char)
                else:
                    result.append(char)
        else:
            # Not a vowel, keep as is
            result.append(char * count)

    sys.stdout.write(''.join(result))

if __name__ == "__main__":
    solve()
