def is_lucky(n):
    """Check if a number is lucky (contains at least one '8')"""
    return '8' in str(n)

def find_min_b(a):
    """Find the minimum positive b such that a + b is lucky"""
    # If a is already lucky, we need to find the next lucky number
    if is_lucky(a):
        # Find the smallest lucky number greater than a
        b = 1
        while not is_lucky(a + b):
            b += 1
        return b
    else:
        # Find the smallest lucky number greater than or equal to a
        b = 1
        while not is_lucky(a + b):
            b += 1
        return b

# Read input
a = int(sys.stdin.readline())

# Find and print the result
print(find_min_b(a))
"}

