prefix_neg = [0] * (n + 1)
prefix_pos = [0] * (n + 1)

for i in range(n):
    prefix_neg[i+1] = prefix_neg[i] + (1 if a[i] < 0 else 0)
    prefix_pos[i+1] = prefix_pos[i] + (1 if a[i] > 0 else 0)

negative_product_count = 0
positive_product_count = 0

for l in range(n):
    for r in range(l, n):
        neg_in_subsegment = prefix_neg[r+1] - prefix_neg[l]
        if neg_in_subsegment % 2 == 1:
            negative_product_count += 1
        else:
            positive_product_count += 1

print(negative_product_count, positive_product_count)
