    # Count males available on this day
    male_count = 0
    for (a, b) in males:
        if a <= day <= b:
            male_count += 1

    # Count females available on this day
    female_count = 0
    for (a, b) in females:
        if a <= day <= b:
            female_count += 1

    # Maximum pairs we can invite
    pairs = min(male_count, female_count)
    total = pairs * 2

    if total > max_friends:
        max_friends = total

print(max_friends)
