    male_count = [0] * 367
    female_count = [0] * 367

    for gender, start, end in friends:
        for day in range(start, end + 1):
            if gender == 'M':
                male_count[day] += 1
            else:
                female_count[day] += 1

    max_friends = 0
    for day in range(1, 367):
        current = 2 * min(male_count[day], female_count[day])
        if current > max_friends:
            max_friends = current

    return max_friends

