    # Count remaining test and social network tabs
    e = 0  # test tabs
    s = 0  # social network tabs

    # Determine which tabs are closed
    closed = set()
    for i in range(1, n + 1):
        if (i - b) % k == 0:
            closed.add(i)

    # Count remaining tabs
    for i in range(1, n + 1):
        if i in closed:
            continue
        if tabs[i - 1] == 1:
            e += 1
        elif tabs[i - 1] == -1:
            s += 1

    diff = abs(e - s)
    max_diff = max(max_diff, diff)

print(max_diff)
