import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = int(data[1])
    b = int(data[2])
    companies = data[3]

    # Convert to 0-indexed
    a -= 1
    b -= 1

    if a == b:
        print(0)
        return

    if companies[a] == companies[b]:
        print(0)
        return

    # Find distance from a to nearest opposite company
    dist_a = float('inf')
    for i in range(n):
        if companies[i] != companies[a]:
            dist_a = min(dist_a, abs(a - i))

    # Find distance from b to nearest opposite company
    dist_b = float('inf')
    for i in range(n):
        if companies[i] != companies[b]:
            dist_b = min(dist_b, abs(b - i))

    print(min(dist_a, dist_b))

if __name__ == "__main__":
    solve()
"}

