n, m = map(int, input().split())

# Track painted cells
painted = set()

for move in range(1, m + 1):
    x, y = map(int, input().split())
    painted.add((x, y))

    # Check if this cell completes a 3x3 square
    # The top-left corner of a 3x3 square could be:
    # (x-2, y-2), (x-2, y-1), (x-2, y)
    # (x-1, y-2), (x-1, y-1), (x-1, y)
    # (x, y-2), (x, y-1), (x, y)

    for dx in range(-2, 1):
        for dy in range(-2, 1):
            i = x + dx
            j = y + dy

            # Check if this is a valid 3x3 square (top-left corner)
            if 1 <= i <= n - 2 and 1 <= j <= n - 2:
                # Check if all 9 cells in this 3x3 square are painted
                all_painted = True
                for dx2 in range(3):
                    for dy2 in range(3):
                        if (i + dx2, j + dy2) not in painted:
                            all_painted = False
                            break
                    if not all_painted:
                        break
                if all_painted:
                    print(move)
                    exit()

print(-1)
"}

