company = input().strip()

# If start and destination are the same
if a == b:
    print(0)
    exit()

# If companies are the same
if company[a-1] == company[b-1]:
    print(0)
    exit()

# Find minimum distance between any airport of company a and any airport of company b
min_cost = float('inf')
for i in range(1, n + 1):
    if company[i-1] == company[a-1]:
        for j in range(1, n + 1):
            if company[j-1] == company[b-1]:
                min_cost = min(min_cost, abs(i - j))

print(min_cost)
"}

