{"code": "
t = int(input())
for _ in range(t):
    n = int(input())

    found = False
    # Try a from 2 to cube root of n
    for a in range(2, int(n ** (1/3)) + 2):
        # Try b from a+1 to sqrt(n/a)
        max_b = int((n // a) ** 0.5)
        for b in range(a + 1, max_b + 1):
            if n % (a * b) == 0:
                c = n // (a * b)
                if c >= 2 and c != a and c != b:
                    print("YES")
                    print(a, b, c)
                    found = True
                    break
        if found:
            break

    if not found:
        print("NO")
"}

