# Closed-form formula: number of cells after t seconds is 1 + 4*t*(t+1)
def count_cells_after_t(t):
    """Calculate the number of cells that are on after t seconds"""
    return 1 + 4 * t * (t + 1)

# Binary search for the minimum t such that count_cells_after_t(t) >= c
low = 0
high = n  # Maximum possible time is when we spread to the edge
answer = 0

while low <= high:
    mid = (low + high) // 2
    cells = count_cells_after_t(mid)
    if cells >= c:
        answer = mid
        high = mid - 1
    else:
        low = mid + 1

print(answer)
