def count_ones_in_range(n, l, r):
    """Efficiently count the number of 1s in range [l, r] for final list of n."""
    def length(n):
        """Compute the length of the final list for element n."""
        if n <= 1:
            return 1
        return 2 * length(n // 2) + 1

    def count(n, l, r):
        """Count the number of 1s in range [l, r] for element n."""
        if n <= 1:
            return n

        # Compute length of left part
        left_len = length(n // 2)

        # If entire range is in left part
        if r <= left_len:
            return count(n // 2, l, r)

        # If entire range is in right part
        if l > left_len:
            return count(n // 2, l - left_len, r - left_len)

        # Otherwise, range spans left, middle, right
        left_count = count(n // 2, l, left_len)
        middle_count = n % 2 if (left_len < l <= left_len + 1) else 0
        right_count = count(n // 2, max(1, l - left_len - 1), r - left_len - 1)

        return left_count + middle_count + right_count

    return count(n, l, r)

