def is_beautiful(s, k):
    """Check if a string is beautiful"""
    count = [0] * 26
    for char in s:
        count[ord(char) - ord('a')] += 1

    for cnt in count:
        if cnt % k != 0:
            return False
    return True

def next_beautiful(n, k, s):
    """Find the next beautiful string >= s"""
    # Check if n is divisible by k
    if n % k != 0:
        return -1

    # Check if s is already beautiful
    if is_beautiful(s, k):
        return s

    # Try to find the next beautiful string
    # Start with s
    chars = list(s)

    while True:
        # Try to increment from right to left
        found = False
        for i in range(len(chars) - 1, -1, -1):
            if chars[i] != 'z':
                chars[i] = chr(ord(chars[i]) + 1)
                found = True
                break

        if not found:
            # We've reached 'z' at all positions
            return -1

        # Check if the new string is beautiful
        if is_beautiful(''.join(chars), k):
            return ''.join(chars)

