    # Read target board
    target = []
    for _ in range(n):
        target.append(input().strip())

    # Read magical bar
    bar = input().strip()

    # Convert to integers
    initial = [[int(c) for c in row] for row in initial]
    target = [[int(c) for c in row] for row in target]
    bar = [int(c) for c in bar]

    # Create a system of equations
    # We need to find row_flips (r) and column_flips (c) such that:
    # initial[i][j] XOR r[i] * bar[j] XOR c[j] * bar[i] == target[i][j]
    # for all i, j

    # This is a system of linear equations modulo 2

    # Create augmented matrix
    matrix = []

    for i in range(n):
        for j in range(n):
            # Equation: r[i] * bar[j] + c[j] * bar[i] = initial[i][j] ^ target[i][j]
            # This equation is for variables r[i] and c[j]

            # Create a row in the matrix
            row = [0] * (2 * n + 1)

            # Coefficient for r[i]
            row[i] = bar[j]

            # Coefficient for c[j]
            row[i + n] = bar[i]

            # Constant term
            row[2 * n] = (initial[i][j] ^ target[i][j])

            matrix.append(row)

    # Gaussian elimination modulo 2
    rank = 0
    for col in range(2 * n):
        # Find pivot
        pivot_row = -1
        for r in range(rank, len(matrix)):
            if matrix[r][col] == 1:
                pivot_row = r
                break

        if pivot_row == -1:
            continue

        # Swap with the current rank row
        matrix[rank], matrix[pivot_row] = matrix[pivot_row], matrix[rank]

        # Eliminate this column from other rows
        for r in range(len(matrix)):
            if r != rank and matrix[r][col] == 1:
                for c in range(col, 2 * n + 1):
                    matrix[r][c] ^= matrix[rank][c]

        rank += 1

    # Now we need to find a particular solution
    # We'll set free variables to 0 and back-substitute
    row_flips = [0] * n
    col_flips = [0] * n

    for r in range(rank - 1, -1, -1):
        # Find pivot column
        pivot_col = -1
        for c in range(2 * n):
            if matrix[r][c] == 1:
                pivot_col = c
                break

        if pivot_col == -1:
            continue

        # The pivot variable is r[pivot_col] if pivot_col < n, else c[pivot_col - n]
        if pivot_col < n:
            # We need to find the value of r[pivot_col]
            # This is the solution for that variable
            value = matrix[r][2 * n]

            # Subtract contributions from other variables
            for c in range(pivot_col + 1, 2 * n):
                if matrix[r][c] == 1:
                    if c < n:
                        value ^= row_flips[c]
                    else:
                        value ^= col_flips[c - n]

