def solve():
    t = int(stdin.readline())
    out_lines = []
    for _ in range(t):
        n = int(stdin.readline().strip())
        p = list(map(int, stdin.readline().strip().split()))

        # We need to check if there exists a partition of p into a and b such that merge(a, b) = p
        # Let's try a recursive approach with backtracking

        from itertools import combinations

        # Try all possible ways to split the elements into a and b
        elements = list(set(p))
        found = False

        def backtrack(pos, left_a, left_b):
            nonlocal found
            if found:
                return
            if pos == 2 * n:
                if not left_a and not left_b:
                    found = True
                return

            val = p[pos]

            # Try assigning to a if val is the minimum of left_a
            if left_a:
                if min(left_a) == val:
                    new_left_a = left_a - {val}
                    backtrack(pos + 1, new_left_a, left_b)

            # Try assigning to b if val is the minimum of left_b
            if left_b:
                if min(left_b) == val:
                    new_left_b = left_b - {val}
                    backtrack(pos + 1, left_a, new_left_b)

        # Start with all elements available
        initial_left_a = set(elements)
        initial_left_b = set()
        backtrack(0, initial_left_a, initial_left_b)

        if found:
            out_lines.append("YES")
        else:
            out_lines.append("NO")

