            return False
    return True

def count_good_subarrays(a):
    """Count the number of good subarrays in array a."""
    n = len(a)
    result = 0

    # Subarrays of length 1 and 2 are good
    result += n + (n * (n - 1)) // 2

    # Check subarrays of length ≥ 3
    for length in range(3, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            if is_good(a[l:r+1]):
                result += 1

