n, k = map(int, input().split())
tabs = list(map(int, input().split()))

max_diff = 0

# Try all possible starting positions b
for b in range(1, n + 1):
    # Calculate which tabs get closed
    closed_tabs = set()
    i = 0
    while True:
        c = b + i * k
        if c > n:
            break
        closed_tabs.add(c)
        i += 1

    # Calculate remaining tabs
    e = 0  # test tabs
    s = 0  # social network tabs
    for i in range(n):
        if i + 1 not in closed_tabs:
            if tabs[i] == 1:
                e += 1
            else:
                s += 1

    diff = abs(e - s)
    if diff > max_diff:
        max_diff = diff

print(max_diff)
