n, m = map(int, input().split())
grid = [input().strip() for _ in range(n)]

# Create adjacency lists for rows and columns
row_adj = [[] for _ in range(n)]
col_adj = [[] for _ in range(m)]

for i in range(n):
    for j in range(m):
        if grid[i][j] == '#':
            row_adj[i].append(j)
            col_adj[j].append(i)

# Try to greedily construct operations
operations = []

# Function to check if a row and column form a complete bipartite subgraph
def is_complete(r, c):
    # Check if all intersections of row r and column c are black
    for j in row_adj[r]:
        if grid[r][j] == '#' and grid[r][j] != '#':
            return False
    for i in col_adj[c]:
        if grid[i][c] == '#' and grid[i][c] != '#':
            return False
    return True

# Try to find a complete bipartite subgraph
rows_remaining = set(range(n))
cols_remaining = set(range(m))

while rows_remaining and cols_remaining:
    # Pick a row
    r = rows_remaining.pop()
    # Find all columns that are adjacent to this row
    cols_adjacent = set(row_adj[r])

    # Find all rows that are adjacent to these columns
    rows_adjacent = set()
    for c in cols_adjacent:
        rows_adjacent.update(col_adj[c])

    # Intersect with remaining rows
    rows_adjacent = rows_adjacent.intersection(rows_remaining)

    if rows_adjacent:
        # Pick one of these rows
        s = rows_adjacent.pop()

        # All cells in these rows and columns should be black
        complete = True
        for i in rows_adjacent | {r}:
            for j in cols_adjacent | {col_adj[s][0]}:
                if grid[i][j] != '#':
                    complete = False
                    break
            if not complete:
                break

        if complete:
            # Add this operation
            operations.append((rows_adjacent | {r}, cols_adjacent | {col_adj[s][0]}))

            # Remove used rows and columns
            rows_remaining -= rows_adjacent | {r}
            cols_remaining -= cols_adjacent | {col_adj[s][0]}

if not rows_remaining and not cols_remaining:
    print("Yes")
else:
    print("No")
