    len_x = 2 * count_ones_range(x // 2, 1, 1) + 1

    # Middle index (1-indexed)
    middle = len_x // 2 + 1

    # Count 1s in left half (positions 1 to middle - 1)
    left_count = 0
    if l <= middle - 1:
        left_l = max(1, l)
        left_r = min(middle - 1, r)
