{"code": "
n = int(input())

# Pattern: if n is even, start with 0, then pairs of (2i, 2i-1)
# if n is odd, start with 1, 0, then from n down to 2
if n % 2 == 0:
    permutation = [0]
    for i in range(1, n // 2 + 1):
        permutation.append(2 * i)
        permutation.append(2 * i - 1)
else:
    permutation = [1, 0]
    for i in range(n - 1, 1, -1):
        permutation.append(i)

beauty = 0
for i in range(len(permutation) - 1):
    beauty += permutation[i] ^ permutation[i + 1]

print(beauty)
print(' '.join(map(str, permutation)))
"}

