def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    nodes = []
    for i in range(n):
        v = int(data[1 + 3*i])
        l = int(data[2 + 3*i])
        r = int(data[3 + 3*i])
        nodes.append((v, l, r))

    # Find root (node that doesn't have a parent)
    children_set = set()
    for i in range(n):
        v, l, r = nodes[i]
        if l != -1:
