zero_count = sum(row.count('0') for row in board)

# Check if board is illegal
if x_count < zero_count or x_count > zero_count + 1:
    print("illegal")
elif check_win(board, 'X'):
    # First player won
    if x_count == zero_count + 1 and not check_win(board, '0'):
        print("the first player won")
    else:
