    female_count = 0

    for (a, b) in males:
        if a <= day <= b:
            male_count += 1

    for (a, b) in females:
        if a <= day <= b:
            female_count += 1

    # Maximum people for this day = 2 * min(male_count, female_count)
    max_people = max(max_people, 2 * min(male_count, female_count))

print(max_people)
