def get_distinct_prime_factors(n):
    factors = set()

    # Check for 2 as a factor
    if n % 2 == 0:
        factors.add(2)
        while n % 2 == 0:
            n //= 2

    # Check for odd factors up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n //= i
        i += 2

    # If n is a prime > 2
    if n > 1:
        factors.add(n)

    return factors

n = int(input())
result = 1
for p in get_distinct_prime_factors(n):
    result *= p
print(result)
